+++ b/src/Symfony/Component/Yaml/Tests/ParserTest.php
@@ -2967,6 +2967,34 @@ public function testParseRejectsDocumentsThatExceedTheDefaultNestingDepth()
         $this->parser->parse($yaml);
     }

+    public function testParseRejectsUnterminatedInlineSequencesThatExceedTheNestingDepth()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Maximum nesting depth of 128 exceeded');
+
+        $this->parser->parse(str_repeat('[', Parser::DEFAULT_MAX_NESTING_LEVEL + 1));
+    }
+
+    public function testParseRejectsUnterminatedInlineMappingsThatExceedTheNestingDepth()
+    {
+        $this->expectException(ParseException::class);
+        $this->expectExceptionMessage('Maximum nesting depth of 128 exceeded');
+
+        $this->parser->parse(str_repeat('{', Parser::DEFAULT_MAX_NESTING_LEVEL + 1));
+    }
+
+    public function testParseAcceptsInlineSequencesAtTheNestingDepth()
+    {
+        $expected = [];
+        for ($i = 1; $i < Parser::DEFAULT_MAX_NESTING_LEVEL; ++$i) {
+            $expected = [$expected];
+        }
+
+        $yaml = str_repeat('[', Parser::DEFAULT_MAX_NESTING_LEVEL).str_repeat(']', Parser::DEFAULT_MAX_NESTING_LEVEL);
+
+        $this->assertSame($expected, $this->parser->parse($yaml));
+    }
+
     public function testParseRejectsDocumentsThatExceedTheConfiguredCollectionAliasLimit()
     {
         $parser = new Parser(Parser::DEFAULT_MAX_NESTING_LEVEL, 5);

From 343a1772ce6ac03e48b228d2d7168d19750e3f36 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Mon, 14 Sep 2026 11:49:55 +0200
Subject: [PATCH 2/5] [HttpFoundation] Remove the ambiguity that makes
 HeaderUtils::split() backtrack

The token branch of the pattern matched whitespace, so a run of whitespace
before a separator could be split between the iterations of the enclosing
quantifier in as many ways as it had characters, and the trailing assertion
forced the engine to enumerate them. Parsing a header holding such runs cost
seconds of CPU, and past the backtracking limit the match failed altogether
and the header was silently parsed as nothing.

Whitespace is now consumed only when more of the value follows it. A value can
therefore never end on whitespace, nothing has to be given back, and every
quantifier can be possessive. What the separator branch sees is unchanged.
Whitespace characters used as separators are left out of the whitespace branch,
so splitting "foo bar" on a space still returns two values.

(cherry picked from commit 47f3a4e2c52a687b2cee188a3ac2275ab5302833)
(cherry picked from commit 9ffa802e5d7e9fb8ba95eeefd27e863e83b1baca)
---
 .../Component/HttpFoundation/HeaderUtils.php  |  9 +++++---
 .../HttpFoundation/Tests/HeaderUtilsTest.php  | 22 ++++++++++++++++++-
 2 files changed, 27 insertions(+), 4 deletions(-)

diff --git a/src/Symfony/Component/HttpFoundation/HeaderUtils.php b/src/Symfony/Component/HttpFoundation/HeaderUtils.php
index 110896e1776d1..697b31823b2cd 100644
--- a/src/Symfony/Component/HttpFoundation/HeaderUtils.php
+++ b/src/Symfony/Component/HttpFoundation/HeaderUtils.php
@@ -58,9 +58,12 @@ public static function split(string $header, string $separators): array
                         "(?:[^"\\\\]|\\\\.)*(?:"|\\\\|$)
                     |
                         # token
-                        [^"'.$quotedSeparators.']+
-                    )+
-                (?<!\s)
+                        [^"\s'.$quotedSeparators.']++
+                    |
+                        # whitespace that is not a separator, only when more of the value follows it,
+                        # so that a value never ends on whitespace and none of it ever has to be given back
+                        [^\S'.$quotedSeparators.']++(?!['.$quotedSeparators.']|$)
+                    )++
             |
                 # separator
                 \s*
diff --git a/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php b/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
index 3279b9a53b47d..28de1e2fd3a89 100644
--- a/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
+++ b/src/Symfony/Component/HttpFoundation/Tests/HeaderUtilsTest.php
@@ -43,6 +43,10 @@ public static function provideHeaderToSplit(): array
             [['foo bar'], 'foo "bar"', ','],
             [['foo bar'], '"foo" bar', ','],
             [['foo bar'], '"foo" "bar"', ','],
+            [['foo', 'bar'], 'foo bar', ' '],
+            [['foo', 'bar'], 'foo   bar', ' '],
+            [[['foo', 'bar'], ['baz']], 'foo bar, baz', ', '],
+            [['foo bar', 'baz'], "foo bar\tbaz", "\t"],

             [[['foo_cookie', 'foo=1&bar=2&baz=3'], ['expires', 'Tue, 22-Sep-2020 06:27:09 GMT'], ['path', '/']], 'foo_cookie=foo=1&bar=2&baz=3; expires=Tue, 22-Sep-2020 06:27:09 GMT; path=/', ';='],
             [[['foo_cookie', 'foo=='], ['expires', 'Tue, 22-Sep-2020 06:27:09 GMT'], ['path', '/']], 'foo_cookie=foo==; expires=Tue, 22-Sep-2020 06:27:09 GMT; path=/', ';='],
@@ -183,4 +187,20 @@ public function testParseQueryIgnoreBrackets()
         $this->assertSame(['a.b[]' => ['A']], HeaderUtils::parseQuery('a.b[]=A', true));
         $this->assertSame(['a.b[]' => ['A']], HeaderUtils::parseQuery('a.b%5B%5D=A', true));
     }
-}
+
+    /**
+     * A run of whitespace before a separator must not make the parser give up: the token branch
+     * of the pattern used to match that whitespace and hand it back one character at a time.
+     */
+    public function testSplitIsNotAmbiguousAboutWhitespaceBeforeSeparators()
+    {
+        $this->assertSame([["a"], ["b"]], HeaderUtils::split("a".str_repeat(" ", 25).",b", ",="));
+        $this->assertSame([[["a"]], [["b"]]], HeaderUtils::split("a".str_repeat(" ", 25).",b", ",;="));
+        $this->assertSame([["x", "1"], ["y", "2"]], HeaderUtils::split("x=1".str_repeat(" ", 25).";y=2", ";="));
+
+        $header = str_repeat("a".str_repeat(" ", 25).",", 200);
+        $this->assertCount(200, HeaderUtils::split($header, ",="));
+
+        // whitespace inside a value is still part of it
+        $this->assertSame([["a b  c"]], HeaderUtils::split("a b  c", ",="));
+    }}

From c2c00c5c15602aa2df98c3e2b313570ab5f26a33 Mon Sep 17 00:00:00 2001
From: Nicolas Grekas <nicolas.grekas@gmail.com>
Date: Thu, 27 Aug 2026 19:59:38 +0200
Subject: [PATCH 3/5] [ExpressionLanguage] Bound the nesting level of parsed
 expressions

The parser stacks one node per nesting level with no limit, so a short crafted
expression builds a node tree tens of thousands of levels deep. Destroying that
tree recurses on the native stack and segfaults the process, before anything is
evaluated. Count the nodes stacked on the branch being built and reject too
deeply nested expressions with a catchable SyntaxError instead.

The nesting level misses the levels that a chain of binary operators or of
property accesses adds above its first operand, so the depth of the node tree
is also checked once parsed.

(cherry picked from commit 9d1056c4673973b8b00dfefda679819c2b6d12ad)
(cherry picked from commit cffd7df2bc47fde62aafcdb3f56dfb6b04502222)
(cherry picked from commit 944be844d18449361c701635974fe7dcc82f774c)
---
 .../Component/ExpressionLanguage/Parser.php   | 87 ++++++++++++++++---
 .../ExpressionLanguage/Tests/ParserTest.php   | 40 +++++++++
 .../ExpressionLanguageSyntaxValidatorTest.php |  1 +
 3 files changed, 115 insertions(+), 13 deletions(-)

diff --git a/src/Symfony/Component/ExpressionLanguage/Parser.php b/src/Symfony/Component/ExpressionLanguage/Parser.php
index 1fabea0078aef..1027e24d80050 100644
--- a/src/Symfony/Component/ExpressionLanguage/Parser.php
+++ b/src/Symfony/Component/ExpressionLanguage/Parser.php
@@ -26,12 +26,15 @@ class Parser
     public const OPERATOR_LEFT = 1;
     public const OPERATOR_RIGHT = 2;

+    private const MAX_NESTING_LEVEL = 256;
+
     private $stream;
     private $unaryOperators;
     private $binaryOperators;
     private $functions;
     private $names;
     private $lint;
+    private $nestingLevel = 0;

     public function __construct(array $functions)
     {
@@ -118,12 +121,18 @@ private function doParse(TokenStream $stream, ?array $names = []): Node\Node
     {
         $this->stream = $stream;
         $this->names = $names;
+        $this->nestingLevel = 0;

         $node = $this->parseExpression();
         if (!$stream->isEOF()) {
             throw new SyntaxError(sprintf('Unexpected token "%s" of value "%s".', $stream->current->type, $stream->current->value), $stream->current->cursor, $stream->getExpression());
         }

+        // a node tree is at most one level deeper than its number of tokens
+        if (self::MAX_NESTING_LEVEL <= \strlen($stream->getExpression())) {
+            $this->checkDepth($node);
+        }
+
         $this->stream = null;
         $this->names = null;

@@ -132,23 +141,33 @@ private function doParse(TokenStream $stream, ?array $names = []): Node\Node

     public function parseExpression(int $precedence = 0)
     {
-        $expr = $this->getPrimary();
-        $token = $this->stream->current;
-        while ($token->test(Token::OPERATOR_TYPE) && isset($this->binaryOperators[$token->value]) && $this->binaryOperators[$token->value]['precedence'] >= $precedence) {
-            $op = $this->binaryOperators[$token->value];
-            $this->stream->next();
-
-            $expr1 = $this->parseExpression(self::OPERATOR_LEFT === $op['associativity'] ? $op['precedence'] + 1 : $op['precedence']);
-            $expr = new Node\BinaryNode($token->value, $expr, $expr1);
+        $nestingLevel = $this->nestingLevel;
+        $this->enterNestingLevel();

+        try {
+            $expr = $this->getPrimary();
             $token = $this->stream->current;
-        }
+            while ($token->test(Token::OPERATOR_TYPE) && isset($this->binaryOperators[$token->value]) && $this->binaryOperators[$token->value]['precedence'] >= $precedence) {
+                $this->enterNestingLevel();
+                $op = $this->binaryOperators[$token->value];
+                $this->stream->next();

-        if (0 === $precedence) {
-            return $this->parseConditionalExpression($expr);
-        }
+                $expr1 = $this->parseExpression(self::OPERATOR_LEFT === $op['associativity'] ? $op['precedence'] + 1 : $op['precedence']);
+                $expr = new Node\BinaryNode($token->value, $expr, $expr1);

-        return $expr;
+                $token = $this->stream->current;
+            }
+
+            if (0 === $precedence) {
+                $this->nestingLevel = $nestingLevel + 1;
+
+                return $this->parseConditionalExpression($expr);
+            }
+
+            return $expr;
+        } finally {
+            $this->nestingLevel = $nestingLevel;
+        }
     }

     protected function getPrimary()
@@ -177,6 +196,7 @@ protected function getPrimary()
     protected function parseConditionalExpression(Node\Node $expr)
     {
         while ($this->stream->current->test(Token::PUNCTUATION_TYPE, '?')) {
+            $this->enterNestingLevel();
             $this->stream->next();
             if (!$this->stream->current->test(Token::PUNCTUATION_TYPE, ':')) {
                 $expr2 = $this->parseExpression();
@@ -336,6 +356,7 @@ public function parsePostfixExpression(Node\Node $node)
         $token = $this->stream->current;
         while (Token::PUNCTUATION_TYPE == $token->type) {
             if ('.' === $token->value) {
+                $this->enterNestingLevel();
                 $this->stream->next();
                 $token = $this->stream->current;
                 $this->stream->next();
@@ -373,6 +394,7 @@ public function parsePostfixExpression(Node\Node $node)

                 $node = new Node\GetAttrNode($node, $arg, $arguments, $type);
             } elseif ('[' === $token->value) {
+                $this->enterNestingLevel();
                 $this->stream->next();
                 $arg = $this->parseExpression();
                 $this->stream->expect(Token::PUNCTUATION_TYPE, ']');
@@ -406,4 +428,43 @@ public function parseArguments()

         return new Node\Node($args);
     }
+
+    /**
+     * Accounts for one more node on the branch being built.
+     *
+     * The nesting level bounds the recursion of the parser.
+     *
+     * @throws SyntaxError
+     */
+    private function enterNestingLevel(): void
+    {
+        if (self::MAX_NESTING_LEVEL < ++$this->nestingLevel) {
+            throw new SyntaxError(sprintf('Expression is nested too deeply, the maximum nesting level is %d', self::MAX_NESTING_LEVEL), $this->stream->current->cursor, $this->stream->getExpression());
+        }
+    }
+
+    /**
+     * Bounds the depth of the resulting node tree.
+     *
+     * Beyond a few thousand levels, serializing or destroying such a tree overflows the native stack.
+     * The nesting level is not enough: it misses the levels that a chain of binary operators or of property accesses adds above its first operand, as in "((a + b + c) + d + e)".
+     *
+     * @throws SyntaxError
+     */
+    private function checkDepth(Node\Node $node): void
+    {
+        $nodes = [[$node, 1]];
+
+        while ($nodes) {
+            [$node, $depth] = array_pop($nodes);
+
+            if (self::MAX_NESTING_LEVEL < $depth) {
+                throw new SyntaxError(sprintf('Expression is nested too deeply, the maximum nesting level is %d', self::MAX_NESTING_LEVEL), $this->stream->current->cursor, $this->stream->getExpression());
+            }
+
+            foreach ($node->nodes as $child) {
+                $nodes[] = [$child, $depth + 1];
+            }
+        }
+    }
 }
diff --git a/src/Symfony/Component/ExpressionLanguage/Tests/ParserTest.php b/src/Symfony/Component/ExpressionLanguage/Tests/ParserTest.php
index d7b5604b9745d..c45189021d488 100644
--- a/src/Symfony/Component/ExpressionLanguage/Tests/ParserTest.php
+++ b/src/Symfony/Component/ExpressionLanguage/Tests/ParserTest.php
@@ -344,4 +344,44 @@ public static function getLintData(): array
             ],
         ];
     }
+
+    /**
+     * @dataProvider getDeeplyNestedExpressions
+     */
+    public function testDeeplyNestedExpressionIsRejected(string $expression)
+    {
+        $this->expectException(SyntaxError::class);
+        $this->expectExceptionMessage('Expression is nested too deeply, the maximum nesting level is 256');
+
+        (new Parser([]))->lint((new Lexer())->tokenize($expression), null);
+    }
+
+    public static function getDeeplyNestedExpressions(): iterable
+    {
+        yield 'unary operators' => [str_repeat('!', 300).'1'];
+        yield 'signs' => [str_repeat('-', 300).'1'];
+        yield 'parentheses' => [str_repeat('(', 300).'1'.str_repeat(')', 300)];
+        yield 'arrays' => [str_repeat('[', 300).'1'.str_repeat(']', 300)];
+        yield 'hashes' => [str_repeat('{a:', 300).'1'.str_repeat('}', 300)];
+        yield 'binary operators' => [str_repeat('1+', 300).'1'];
+        yield 'properties' => ['a'.str_repeat('.b', 300)];
+        yield 'array accesses' => ['a'.str_repeat('[0]', 300)];
+        yield 'ternaries' => [str_repeat('1?', 300).'1'.str_repeat(':1', 300)];
+        yield 'binary operators in nested parentheses' => [str_repeat('(', 20).'1'.str_repeat(str_repeat(' + 1', 20).')', 20)];
+        yield 'properties in nested parentheses' => [str_repeat('(', 20).'a'.str_repeat(str_repeat('.b', 20).')', 20)];
+    }
+
+    public function testDeepButReasonableExpressionIsAccepted()
+    {
+        (new Parser([]))->lint((new Lexer())->tokenize(str_repeat('(', 100).'a'.str_repeat(' + 1)', 100)), ['a']);
+
+        $this->expectNotToPerformAssertions();
+    }
+
+    public function testChainedTernariesWithBinaryConditionsAreAccepted()
+    {
+        (new Parser([]))->lint((new Lexer())->tokenize(str_repeat('a and a and a ? 1 : ', 64).'0'), ['a']);
+
+        $this->expectNotToPerformAssertions();
+    }
 }
